<?php declare(strict_types=1);require_once __DIR__.'/auth_check.php';require_once __DIR__.'/bootstrap.php';$db=app_database();$_SESSION['supplier_csrf']??=bin2hex(random_bytes(24));$error='';if($_SERVER['REQUEST_METHOD']==='POST')try{if(!hash_equals((string)$_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Session expirée.');$verified=(new App\Application\Supplier\VerifySupplierNcc())->execute((string)($_POST['ncc']??''));$s=$db->prepare("INSERT INTO suppliers(ncc,name,address,phone,email,tax_regime,activity_status,ncc_verified_at,ncc_payload,active)VALUES(:ncc,:name,:address,:phone,:email,:regime,:activity,NOW(),:payload,1) ON DUPLICATE KEY UPDATE name=VALUES(name),address=VALUES(address),phone=VALUES(phone),email=VALUES(email),tax_regime=VALUES(tax_regime),activity_status=VALUES(activity_status),ncc_verified_at=NOW(),ncc_payload=VALUES(ncc_payload),active=1");$s->execute(['ncc'=>$verified['ncc'],'name'=>$verified['name'],'address'=>trim((string)($_POST['address']??''))?:null,'phone'=>trim((string)($_POST['phone']??''))?:null,'email'=>trim((string)($_POST['email']??''))?:null,'regime'=>$verified['tax_regime'],'activity'=>$verified['activity_status'],'payload'=>json_encode($verified['payload'],JSON_UNESCAPED_UNICODE)]);$_SESSION['supplier_csrf']=bin2hex(random_bytes(24));header('Location: fournisseurs.php?saved=1');exit;}catch(Throwable$e){$error=$e->getMessage();}$q=trim((string)($_GET['q']??''));$s=$db->prepare("SELECT * FROM suppliers WHERE active=1 AND (:q='' OR ncc LIKE :likeq OR name LIKE :likeq2) ORDER BY name");$s->execute(['q'=>$q,'likeq'=>'%'.$q.'%','likeq2'=>'%'.$q.'%']);$rows=$s->fetchAll();function sh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fournisseurs · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>.sup{max-width:1250px}.hero{padding:27px;color:#fff;background:linear-gradient(120deg,var(--brand-primary),#41477b);border-radius:22px}.hero h1{color:#fff!important}.layout{display:grid;grid-template-columns:420px 1fr;gap:18px;margin-top:18px}.panel{padding:21px;background:#fff;border:1px solid var(--brand-border);border-radius:18px}.supplier-card{padding:15px;margin-top:10px;border:1px solid #e3e5ec;border-radius:13px}.verified{color:#087c48;background:#def7e9;padding:4px 8px;border-radius:99px;font-size:.7rem}@media(max-width:900px){.layout{grid-template-columns:1fr}}</style></head><body class="module-page"><?php include __DIR__.'/partials/navbar.php';?><main class="container sup"><header class="hero"><small>RÉFÉRENTIEL ACHATS</small><h1>Gestion des fournisseurs</h1><p>Le NCC est vérifié auprès du service FNE de la Direction générale des Impôts avant tout enregistrement.</p></header><?php if($error):?><div class="alert alert-danger mt-3"><?=sh($error)?></div><?php elseif(isset($_GET['saved'])):?><div class="alert alert-success mt-3">La fiche fournisseur vérifiée a été enregistrée.</div><?php endif;?><div class="layout"><section class="panel"><h2 class="h5">Nouvelle fiche fournisseur</h2><form method="post" id="supplierForm"><input type="hidden" name="csrf" value="<?=sh($_SESSION['supplier_csrf'])?>"><label class="form-label fw-bold">Numéro de compte contribuable (NCC)</label><div class="input-group"><input class="form-control" id="ncc" name="ncc" required placeholder="Ex. 2242142V"><button class="btn btn-warning" id="lookup" type="button">Remplir la fiche</button></div><div id="lookupStatus" class="small mt-2 text-muted">Saisissez le NCC puis interrogez la fiche DGI.</div><label class="form-label mt-3">Raison sociale vérifiée<input class="form-control" id="name" readonly required></label><label class="form-label">Régime fiscal<input class="form-control" id="regime" readonly></label><label class="form-label">Statut d’activité<input class="form-control" id="activity" readonly></label><label class="form-label">Adresse<input class="form-control" name="address"></label><div class="row"><label class="col form-label">Téléphone<input class="form-control" name="phone"></label><label class="col form-label">E-mail<input class="form-control" type="email" name="email"></label></div><button id="save" class="btn btn-primary w-100" disabled>Valider le fournisseur</button></form></section><section class="panel"><form><div class="input-group"><input class="form-control" name="q" value="<?=sh($q)?>" placeholder="Rechercher par NCC ou raison sociale"><button class="btn btn-outline-primary">Rechercher</button></div></form><?php foreach($rows as$r):?><article class="supplier-card"><div class="d-flex justify-content-between"><div><strong><?=sh($r['name'])?></strong><small class="d-block text-muted">NCC <?=sh($r['ncc'])?> · <?=sh($r['tax_regime'])?></small></div><span class="verified">DGI vérifié</span></div><p class="mb-0 mt-2 small"><?=sh(implode(' · ',array_filter([$r['address'],$r['phone'],$r['email']])))?></p></article><?php endforeach;?><?php if(!$rows):?><div class="text-center text-muted py-5">Aucun fournisseur enregistré.</div><?php endif;?></section></div></main><script>const ncc=document.getElementById('ncc'),statusBox=document.getElementById('lookupStatus'),save=document.getElementById('save');document.getElementById('lookup').onclick=async()=>{save.disabled=true;statusBox.textContent='Vérification auprès de la DGI…';try{const r=await fetch('request/lookup_supplier_ncc.php?ncc='+encodeURIComponent(ncc.value));const j=await r.json();if(!j.ok)throw new Error(j.message);name.value=j.supplier.name;regime.value=j.supplier.tax_regime;activity.value=j.supplier.activity_status;statusBox.textContent='NCC vérifié. Complétez les coordonnées puis validez.';statusBox.className='small mt-2 text-success';save.disabled=false}catch(e){statusBox.textContent=e.message;statusBox.className='small mt-2 text-danger'}};ncc.oninput=()=>save.disabled=true;</script></body></html>
